CREATE OR REPLACE FUNCTION public.challenge_save_result(p_device_id text, p_type text, p_letter text, p_timed boolean, p_words jsonb)
 RETURNS TABLE(id bigint, score integer, challenge_date date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_device text := nullif(trim(coalesce(p_device_id, '')), '');
  v_today date := (now() at time zone 'Europe/Bratislava')::date;
  v_day date;
  v_letter text := upper(coalesce(p_letter, ''));
  v_words jsonb := coalesce(p_words, '[]'::jsonb);
  v_score integer;
  v_plays integer;
  v_bad integer;
begin
  if v_user is null and v_device is null then raise exception 'challenge: no identity' using errcode = '22023'; end if;
  if v_device is not null and v_device !~ '^[A-Za-z0-9-]{8,64}$' then raise exception 'challenge: bad device id' using errcode = '22023'; end if;
  if v_letter = public.challenge_letter(v_today) then v_day := v_today;
  elsif v_letter = public.challenge_letter(v_today - 1) then v_day := v_today - 1;
  else raise exception 'challenge: not the letter of the day' using errcode = '22023'; end if;
  if jsonb_typeof(v_words) <> 'array' or jsonb_array_length(v_words) > 500 then raise exception 'challenge: bad words' using errcode = '22023'; end if;
  select count(*) into v_bad from jsonb_array_elements(v_words) e
   where jsonb_typeof(e) <> 'object'
      or jsonb_typeof(e -> 'word') is distinct from 'string' or length(e ->> 'word') > 40
      or coalesce(e ->> 'verdict', '') not in ('correct', 'misspelled', 'wrong', 'duplicate')
      or (e ? 'correction' and (jsonb_typeof(e -> 'correction') <> 'string' or length(e ->> 'correction') > 40));
  if v_bad > 0 then raise exception 'challenge: bad word entry' using errcode = '22023'; end if;
  select least(150, count(distinct w)) into v_score from (
    select regexp_replace(lower(trim(e ->> 'word')), '[.,!?;:"'')]+$', '') as w
      from jsonb_array_elements(v_words) e where e ->> 'verdict' = 'correct'
  ) x where w ~ '^[a-z]{2,40}$' and left(w, 1) = lower(v_letter);
  select count(*) into v_plays from public.challenge_results r
   where r.challenge_date = v_day and (case when v_user is not null then r.user_id = v_user else r.user_id is null and r.device_id = v_device end);
  if v_plays >= 200 then raise exception 'challenge: daily cap' using errcode = '54000'; end if;
  return query
  insert into public.challenge_results as r (user_id, device_id, challenge_type, challenge_date, letter, score, timed, words)
  values (v_user, case when v_user is null then v_device else null end, p_type, v_day, v_letter, v_score, coalesce(p_timed, false), v_words)
  returning r.id, r.score, r.challenge_date;
end;
$function$
